 ));
$pdo=Database::connection();$token=(string)($_GET['token']??$_POST['token']??'');$session=TestAutomaticJudgeService::byToken($pdo,$token);if(!$session){if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_score'){while(ob_get_level()>0)ob_end_clean();http_response_code(409);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode(['ok'=>false,'error'=>'This test judge link was refreshed or expired. Open the latest secure judge link and continue scoring.'],JSON_UNESCAPED_SLASHES);exit;}http_response_code(404);exit('This test judge link was refreshed or expired. Open the latest secure judge link.');}
$flightSummary=ScoringFlightService::summary($pdo,(int)$session['round_id'],true);$flightCount=(int)($flightSummary['flight_count']??0);$activeFlight=max(1,(int)($flightSummary['active_flight']??1));$flightsEnabled=$flightCount>0;$viewRound=$flightsEnabled?max(1,min($flightCount,(int)($_GET['scoring_round']??$_POST['scoring_round']??1))):1;
$sessionId=(int)$session['id'];$roundId=(int)$session['round_id'];$judgeId=(int)$session['judge_id'];$error='';$notice='';if(isset($_GET['status'])){header('Content-Type:application/json');header('Cache-Control:no-store');echo json_encode(['status'=>$session['status'],'criteria_required'=>JudgingCriteriaService::requiresAcceptance($session)]);exit;}TestAutomaticJudgeService::markOpened($pdo,$sessionId);$quotaAsset=e(url('public/js/test-judge-heats-quotas-v188.js'));ob_start(static fn(string $html):string=>str_replace('</head>','<script defer src="'.$quotaAsset.'"></script><style>.mark-btn label.quota-unavailable{opacity:.35}.counter.complete{border-color:#198754;background:#e8f6ed}.mark-btn input[value=yes]+label{border-color:#198754;color:#198754}.mark-btn input[value=yes]:checked+label{background:#198754;color:#fff;border-color:#198754}.mark-btn input[value=alt1]+label{border-color:#D4A017;color:#8a6800}.mark-btn input[value=alt1]:checked+label{background:#D4A017;color:#000;border-color:#D4A017}.mark-btn input[value=alt2]+label{border-color:#708090;color:#536273}.mark-btn input[value=alt2]:checked+label{background:#708090;color:#fff;border-color:#708090}.mark-btn input[value=alt3]+label{border-color:#B86B3D;color:#8c4d28}.mark-btn input[value=alt3]:checked+label{background:#B86B3D;color:#fff;border-color:#B86B3D}.mark-btn input[value=no]+label{border-color:#DC3545;color:#DC3545}.mark-btn input[value=no]:checked+label{background:#DC3545;color:#fff;border-color:#DC3545}</style></head>',$html));
$rs=$pdo->prepare('SELECT yes_count,callback_count,yes_weight,alt1_weight,alt2_weight,alt3_weight FROM bdc_test_scoring_rounds WHERE id=:r');$rs->execute(['r'=>$roundId]);$round=$rs->fetch();$scope=(string)$session['scoring_scope'];$sql="SELECT * FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active'";$params=['r'=>$roundId];if($scope!=='all'){$sql.=' AND dance_role=:role';$params['role']=$scope;}$sql.=' ORDER BY dance_role,bib_number';$q=$pdo->prepare($sql);$q->execute($params);$allEntries=$q->fetchAll();$entries=$allEntries;if($flightsEnabled){$flightMap=ScoringFlightService::assignmentMap($pdo,$roundId,true,'entry');$entries=array_values(array_filter($allEntries,static fn(array $entry):bool=>(int)($flightMap[(int)$entry['id']]['flight']??0)===$viewRound));}$byRole=['leader'=>[],'follower'=>[]];foreach($entries as $entry)$byRole[$entry['dance_role']][]=$entry;
$testYesLimit=max(1,(int)($round['yes_count']??10));$testCountStmt=$pdo->prepare("SELECT dance_role,COUNT(*) total FROM bdc_test_scoring_entries WHERE round_id=:round AND entry_status='active' GROUP BY dance_role");$testCountStmt->execute(['round'=>$roundId]);$testRoleCounts=['leader'=>0,'follower'=>0];foreach($testCountStmt->fetchAll() as $countRow){$countRole=(string)$countRow['dance_role'];if(isset($testRoleCounts[$countRole]))$testRoleCounts[$countRole]=(int)$countRow['total'];}$testRolePlan=RoleAdvancementService::roundPlan($testRoleCounts['leader'],$testRoleCounts['follower'],$testYesLimit);$allEntries=array_values(array_filter($allEntries,static fn(array $entry):bool=>!($testRolePlan[(string)$entry['dance_role']]['direct_to_final']??false)));$entries=array_values(array_filter($entries,static fn(array $entry):bool=>!($testRolePlan[(string)$entry['dance_role']]['direct_to_final']??false)));$byRole=['leader'=>[],'follower'=>[]];foreach($entries as $entry)$byRole[$entry['dance_role']][]=$entry;$testOrdinal=static function(int $number):string{$mod100=$number%100;if($mod100>=11&&$mod100<=13)return $number.'th';return $number.(match($number%10){1=>'st',2=>'nd',3=>'rd',default=>'th'});};$testRoundLabel=(string)$session['round_type']==='semifinal'?'Semifinal':'Heats';$testA1Place=$testOrdinal($testYesLimit+1);$testA2Place=$testOrdinal($testYesLimit+2);$testA3Place=$testOrdinal($testYesLimit+3);
function validateMarks(array $roles,array $marks,int $limit,bool $submit):void{foreach($roles as $role=>$rows){if(!$rows)continue;$yes=0;$alts=[1=>0,2=>0,3=>0];foreach($rows as $row){$v=(string)($marks[(int)$row['id']]??'no');if($v==='yes')$yes++;elseif(str_starts_with($v,'alt'))$alts[(int)substr($v,-1)]++;}if($yes>$limit)throw new RuntimeException('Maximum '.$limit.' YES selections allowed for '.ucfirst($role).'s.');foreach($alts as $n=>$count)if($count>1)throw new RuntimeException('A'.$n.' can only be assigned once for '.ucfirst($role).'s.');$required=min($limit,count($rows));if($submit&&$yes!==$required)throw new RuntimeException('Select exactly '.$required.' YES for '.ucfirst($role).'s before submitting.');$requiredAlts=min(3,max(0,count($rows)-$required));foreach($alts as $n=>$count){$needed=$n<=$requiredAlts?1:0;if($submit&&$count!==$needed)throw new RuntimeException(($needed?'Select exactly one ':'Do not select ').'A'.$n.' for '.ucfirst($role).'s before submitting.');}}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='accept_criteria'){if(!Csrf::verify($_POST['_csrf']??null)||($_POST['criteria_confirm']??'')!=='1'){http_response_code(422);exit('Confirm that you have read and accept the judging criteria.');}TestAutomaticJudgeService::acceptCriteria($pdo,$sessionId);header('Location: '.url('test-judge-scoring/?token='.rawurlencode($token)),true,303);exit;}
if(JudgingCriteriaService::requiresAcceptance($session)){?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Judging Criteria</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">BDC Automatic Scoring TEST</span><span class="badge text-bg-warning">TEST ONLY</span></div></nav><main class="container py-4" style="max-width:760px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3">Judging Criteria</h1><p class="text-muted"><?=e($session['event_name'])?> · <?=e($session['judge_name'])?></p><div class="row g-2 mb-3"><?php foreach(JudgingCriteriaService::weights() as [$name,$weight]):?><div class="col-6"><div class="border rounded p-2 d-flex justify-content-between"><strong><?=e($name)?></strong><span><?=e($weight)?></span></div></div><?php endforeach;?></div><div class="alert alert-info"><?php if($session['round_type']==='final'):$testRankLimit=max(1,(int)($round['callback_count']??10));?><strong>Final, Relative Placement:</strong> Rank your <strong>TOP <?=$testRankLimit?></strong> best couples from 1 to <?=$testRankLimit?>. Use each rank once. Leave all other couples as <strong>NO RANK</strong>.<?php else:?><strong><?=e($testRoundLabel)?> Instructions</strong><ul class="mb-0 mt-2"><li>Choose <strong><?=$testYesLimit?> YES</strong> for your <strong>Top <?=$testYesLimit?> best dancers</strong>.</li><li>Alternative picks: A1 = <strong><?=e($testA1Place)?> place</strong>, A2 = <strong><?=e($testA2Place)?> place</strong>, A3 = <strong><?=e($testA3Place)?> place</strong>.</li><li>Mark everyone else <strong>NO</strong>.</li><li>Use the optional comment field for a private note.</li></ul><?php endif;?></div><p>Judge independently and confidentially. Do not discuss or compare selections with another judge before submitting.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="action" value="accept_criteria"><label class="form-check mb-3"><input class="form-check-input" id="criteriaConfirm" type="checkbox" name="criteria_confirm" value="1"><span class="form-check-label">I have read and accept the judging criteria.</span></label><button id="startScoring" class="btn btn-success w-100" disabled>Start Scoring</button></form></div></div></main><script>const c=document.getElementById('criteriaConfirm'),b=document.getElementById('startScoring');c.onchange=()=>b.disabled=!c.checked;</script></body></html><?php exit;}
