if($flightsEnabled){ob_start(static function(string $html)use($token,$flightCount,$viewRound):string{$tabs='<div class="alert alert-primary text-center"><strong class="d-block mb-2">SELECT SCORING ROUND</strong><div class="d-flex gap-2 justify-content-center flex-wrap">';for($roundTab=1;$roundTab<=$flightCount;$roundTab++){$active=$roundTab===$viewRound?'btn-primary':'btn-outline-primary';$tabs.='<a class="btn '.$active.' fw-bold" href="?token='.rawurlencode($token).'&amp;scoring_round='.$roundTab.'">ROUND '.$roundTab.'</a>';}$tabs.='</div><small class="d-block mt-2">Review every round, then submit once.</small></div>';return str_replace('<h1 class="h3">',$tabs.'<h1 class="h3">',$html);});}
try{if($_SERVER['REQUEST_METHOD']==='POST'){if((string)$session['status']==='submitted')throw new RuntimeException('Scores are already submitted and locked.');if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'save');$marks=$_POST['mark']??[];if($action==='generate_random'){$marks=[];foreach($byRole as $rows){$ids=array_map(fn($e)=>(int)$e['id'],$rows);shuffle($ids);foreach($ids as $id)$marks[$id]='no';$yes=min((int)$round['yes_count'],count($ids));for($i=0;$i<$yes;$i++)$marks[$ids[$i]]='yes';$cursor=$yes;foreach([1,2,3] as $alt)if(isset($ids[$cursor]))$marks[$ids[$cursor++]]='alt'.$alt;}}if($action!=='submit')validateMarks($byRole,$marks,(int)$round['yes_count'],false);$up=$pdo->prepare("INSERT INTO bdc_test_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score,updated_by) VALUES(:r,:e,:j,:t,:a,:w,NULL) ON DUPLICATE KEY UPDATE mark_type=VALUES(mark_type),alt_rank=VALUES(alt_rank),weighted_score=VALUES(weighted_score),updated_at=NOW()");foreach($entries as $entry){$value=(string)($marks[(int)$entry['id']]??'no');$type='blank';$alt=null;$weight=0.0;if($value==='yes'){$type='yes';$weight=(float)$round['yes_weight'];}elseif(str_starts_with($value,'alt')){$type='alt';$alt=(int)substr($value,-1);$weight=(float)$round['alt'.$alt.'_weight'];}$up->execute(['r'=>$roundId,'e'=>$entry['id'],'j'=>$judgeId,'t'=>$type,'a'=>$alt,'w'=>$weight]);}if($action==='submit'){$globalMarks=[];$saved=$pdo->prepare('SELECT entry_id,mark_type,alt_rank FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j');$saved->execute(['r'=>$roundId,'j'=>$judgeId]);foreach($saved->fetchAll() as $savedRow){$globalMarks[(int)$savedRow['entry_id']]=$savedRow['mark_type']==='yes'?'yes':($savedRow['mark_type']==='alt'?'alt'.(int)$savedRow['alt_rank']:'no');}$globalRoles=['leader'=>[],'follower'=>[]];foreach($allEntries as $globalEntry)$globalRoles[$globalEntry['dance_role']][]=$globalEntry;validateMarks($globalRoles,$globalMarks,(int)$round['yes_count'],true);}TestAutomaticJudgeService::markSaved($pdo,$sessionId);if($action==='submit'){TestAutomaticJudgeService::submit($pdo,$sessionId);$notice='Scores submitted and locked.';}elseif($action==='generate_random')$notice='Valid random test scores generated.';else$notice='Scores saved.';$session=TestAutomaticJudgeService::byToken($pdo,$token);}}catch(Throwable $e){$error=$e->getMessage();}
$existing=[];$m=$pdo->prepare('SELECT entry_id,mark_type,alt_rank FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j');$m->execute(['r'=>$roundId,'j'=>$judgeId]);foreach($m->fetchAll() as $row){$value=$row['mark_type']==='yes'?'yes':($row['mark_type']==='alt'?'alt'.(int)$row['alt_rank']:'no');$existing[(int)$row['entry_id']]=$value;}$locked=(string)$session['status']==='submitted';$counts=['leader'=>['yes'=>0,1=>0,2=>0,3=>0],'follower'=>['yes'=>0,1=>0,2=>0,3=>0]];foreach($entries as $entry){$value=$existing[(int)$entry['id']]??'no';$role=$entry['dance_role'];if($value==='yes')$counts[$role]['yes']++;elseif(str_starts_with($value,'alt'))$counts[$role][(int)substr($value,-1)]++;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Judge Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.score-row{background:#fff;border:1px solid #dee2e6;border-radius:12px;padding:12px;margin-bottom:9px}.mark-btn{display:grid!important;grid-template-columns:repeat(5,1fr);gap:6px!important}.mark-btn span,.mark-btn label{width:100%}.mark-btn input{display:none}.mark-btn label{min-width:0;padding:8px 3px;font-size:13px}.mark-btn input:checked+label{background:#212529;color:#fff}.counter{position:sticky;top:0;z-index:4;background:#fff;border:1px solid #dee2e6;border-radius:10px;padding:10px;margin-bottom:12px}.heats-comment{margin-top:8px;font-size:14px}.heats-comment input{min-height:34px}@media(max-width:520px){.mark-btn{gap:4px!important}.mark-btn label{font-size:12px;padding:8px 1px}}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">BDC Automatic Scoring TEST</span><span class="badge text-bg-warning">TEST ONLY</span></div></nav><main class="container py-4" style="max-width:900px"><h1 class="h3"><?=e($session['event_name'])?></h1><div class="text-muted mb-3"><?=e($session['division'])?> · <?=e($session['judge_name'])?><?=((int)$session['is_chief']===1?' · Chief Judge':'')?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><div class="alert alert-info"><strong><?=e($testRoundLabel)?> Instructions</strong><ul class="mb-0 mt-2"><li>Choose <strong><?=$testYesLimit?> YES</strong> for your <strong>Top <?=$testYesLimit?> best dancers</strong>.</li><li>A1 = <strong><?=e($testA1Place)?> place</strong>, A2 = <strong><?=e($testA2Place)?> place</strong>, A3 = <strong><?=e($testA3Place)?> place</strong>.</li><li>Mark everyone else <strong>NO</strong>.</li><li>Comments are optional and private to this judge/device.</li></ul></div><?php if(!$locked):?><form method="post" class="mb-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><button class="btn btn-warning" name="action" value="generate_random">Generate Valid Random Scores</button></form><?php endif;?><?php foreach(['leader'=>'Leaders','follower'=>'Followers'] as $role=>$label):if(!$byRole[$role])continue;?><div class="counter"><strong><?=$label?></strong> · YES <?=$counts[$role]['yes']?>/<?=(int)$round['yes_count']?> · A1 <?=$counts[$role][1]?>/1 · A2 <?=$counts[$role][2]?>/1 · A3 <?=$counts[$role][3]?>/1</div><?php endforeach;?><?php if($locked):?><div class="alert alert-success"><strong>Submitted.</strong> These scores are locked.</div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="token" value="<?=e($token)?>"><?php foreach($entries as $entry):$id=(int)$entry['id'];$selected=$existing[$id]??'no';?><div class="score-row" id="entry<?=$id?>" data-name="<?=e($entry['display_name'])?>"><strong>#<?=(int)$entry['bib_number']?> <?=e($entry['display_name'])?></strong><div class="small text-muted mb-2"><?=e(ucfirst($entry['dance_role']))?></div><div class="mark-btn"><?php foreach(['yes'=>'YES','alt1'=>'A1','alt2'=>'A2','alt3'=>'A3','no'=>'NO'] as $value=>$label):?><span><input id="m<?=$id?>-<?=$value?>" type="radio" name="mark[<?=$id?>]" value="<?=$value?>" <?=($selected===$value?'checked':'')?> <?=($locked?'disabled':'')?>><label class="btn btn-outline-dark" for="m<?=$id?>-<?=$value?>"><?=$label?></label></span><?php endforeach;?></div><div class="heats-comment"><input class="form-control form-control-sm heats-comment-input" data-entry="<?=$id?>" maxlength="160" placeholder="Optional private comment" <?=($locked?'disabled':'')?>></div></div><?php endforeach;?><?php if(!$locked):?><div class="position-sticky bottom-0 bg-light py-3 d-flex gap-2"><button class="btn btn-outline-primary flex-fill" name="action" value="save">Save Draft</button><button class="btn btn-success flex-fill" name="action" value="submit" onclick="return confirm('Submit and lock your scores?')">Submit &amp; Lock</button></div><?php endif;?></form></main><?php if(!$locked):?><script>document.querySelectorAll('.heats-comment-input').forEach(input=>{const key='bdc-test-heats-comment-<?=$roundId?>-<?=$judgeId?>-'+input.dataset.entry;input.value=localStorage.getItem(key)||'';input.addEventListener('input',()=>localStorage.setItem(key,input.value));});</script><?php endif;?></body></html>
